import{_ as i,o as a,c as o,ag as n}from"./chunks/framework.BGkQCay2.js";const m=JSON.parse('{"title":"vex-cli Reference","description":"","frontmatter":{},"headers":[],"relativePath":"references/vex-cli-reference.md","filePath":"references/vex-cli-reference.md"}'),r={name:"references/vex-cli-reference.md"};function l(t,e,s,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="vex-cli-reference" tabindex="-1">vex-cli Reference <a class="header-anchor" href="#vex-cli-reference" aria-label="Permalink to &quot;vex-cli Reference&quot;">​</a></h1><p>This document describes <code>vex-cli</code> architecture, command pipeline, and extension points.</p><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><code>vex-cli</code> is the primary developer-facing command-line entry for:</p><ul><li>compile (<code>vex compile</code>)</li><li>run (<code>vex run</code>)</li><li>test (<code>vex test</code>)</li><li>semantic analysis and verified cleanup (<code>vex lint</code>)</li><li>toolchain integration with diagnostics, optimizer remarks, and package/native resolution</li></ul><hr><h2 id="command-surface" tabindex="-1">Command Surface <a class="header-anchor" href="#command-surface" aria-label="Permalink to &quot;Command Surface&quot;">​</a></h2><p>Main command modules are under:</p><ul><li><code>tools/vex-cli/src/commands/compile.rs</code></li><li><code>tools/vex-cli/src/commands/run.rs</code></li><li><code>tools/vex-cli/src/commands/test.rs</code></li><li><code>tools/vex-cli/src/commands/lint.rs</code></li><li><code>tools/vex-cli/src/commands/pipeline.rs</code></li></ul><h3 id="vex-compile" tabindex="-1"><code>vex compile</code> <a class="header-anchor" href="#vex-compile" aria-label="Permalink to &quot;`vex compile`&quot;">​</a></h3><p>Responsibilities:</p><ol><li>Resolve dependencies via <code>vex-pm</code></li><li>Build compiler pipeline via <code>CompilerDriver</code></li><li>Generate object file from LLVM module</li><li>Link executable with: <ul><li>runtime linker args (<code>vex_runtime::get_linker_args()</code>)</li><li>native package linker args (<code>vex_pm::get_native_linker_args_for_source(...)</code>)</li></ul></li><li>Emit optional artifacts (<code>.ll</code>, CFG, coverage)</li></ol><h3 id="vex-run" tabindex="-1"><code>vex run</code> <a class="header-anchor" href="#vex-run" aria-label="Permalink to &quot;`vex run`&quot;">​</a></h3><p>Responsibilities:</p><ol><li>Resolve deps + compile module</li><li>Link temporary executable with runtime + merged native linker args</li><li>Execute and report timings</li></ol><h3 id="vex-test" tabindex="-1"><code>vex test</code> <a class="header-anchor" href="#vex-test" aria-label="Permalink to &quot;`vex test`&quot;">​</a></h3><p>Responsibilities:</p><ol><li>Discover <code>*.test.vx</code> / <code>_test.vx</code></li><li>Generate test runner main when needed</li><li>Execute each test function with pass/fail markers</li><li>Handle compile errors and summarize results</li></ol><h3 id="vex-lint" tabindex="-1"><code>vex lint</code> <a class="header-anchor" href="#vex-lint" aria-label="Permalink to &quot;`vex lint`&quot;">​</a></h3><p>Responsibilities:</p><ol><li>Resolve a <code>.vx</code>/<code>.vxc</code> file, package directory, or nearest <code>vex.json</code></li><li>Run correctness analysis and the shared <code>vex-lint</code> semantic registry without LLVM</li><li>Apply manifest and CLI rule/group levels with CLI precedence</li><li>Emit deterministic text, canonical JSON, or SARIF 2.1.0 diagnostics, including suppression metadata</li><li>Plan revision-bound edits, reject conflicts, and verify semantics for up to four passes</li><li>Atomically write only a fully verified workspace, or print it with <code>--diff</code></li></ol><p>Core options are <code>--fix</code>, <code>--diff</code>, <code>--format text|json|sarif</code>, <code>--deny-warnings</code>, <code>--allow</code>, <code>--warn</code>, <code>--deny</code>, <code>--only</code>, <code>--target</code>, <code>--explain-boxing</code> and <code>--explain-arena</code>. <code>--timings</code> adds opt-in per-rule telemetry to JSON/SARIF; normal runs have no clock-read overhead. The former <code>check</code>, <code>analyze</code> and <code>fix</code> compatibility commands have been removed.</p><p><code>--write-baseline PATH</code> atomically records the current lint set for staged CI; <code>--baseline PATH</code> loads it. Matching findings remain in every output format but do not fail lint warning/deny gates. Correctness errors are never baselined. <code>lint.baseline</code> in <code>vex.json</code> provides a package-relative default.</p><p>Directory inventory is package-scoped: nested manifests and transient test/benchmark runners are not merged into the target. Ordinary lint uses the diagnostics-oriented HIR path and skips codegen module flattening. Full semantic fingerprints are reserved for verified <code>--fix</code>/<code>--diff</code> runs.</p><p>Canonical forms:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --diff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span></code></pre></div><p><code>--fix</code> writes only after the in-memory result reaches a verified fixed point. <code>--diff</code> runs the same planner and verifier but prints the patch. Syntax-only migrations can operate beside an unrelated pre-existing correctness error; semantic fixes require their proving phase and cannot introduce or alter a correctness failure.</p><p>Rule configuration is read from the nearest <code>vex.json</code>. CLI rule/group levels override manifest levels. Local <code>vex-lint: allow-file</code> and <code>allow-next</code> directives use stable symbolic IDs and are included in JSON metadata.</p><p>The current registry also covers resolved <code>Result</code>/<code>Future</code> misuse, target-aware numeric ranges, allocation effects, and exported API audits. Performance, API, and pedantic rules are opt-in through the <code>performance</code>, <code>library</code>, <code>pedantic</code>, and <code>strict</code> profiles. Semantic body rules share one lazy, revision-bound fact graph with exact call identities and transitive effect summaries. See <a href="/docs/guide/tooling/lint">Linting and Verified Fixes</a> for the complete rule table, configuration, exit codes, suppression syntax, and stability boundary.</p><hr><h2 id="compiler-integration" tabindex="-1">Compiler Integration <a class="header-anchor" href="#compiler-integration" aria-label="Permalink to &quot;Compiler Integration&quot;">​</a></h2><p><code>vex-cli</code> delegates language pipeline to <code>CompilerDriver</code>:</p><ul><li>parsing</li><li>lowering</li><li>type/borrow checks</li><li>codegen</li></ul><p>This keeps command handlers thin while preserving shared compilation behavior.</p><hr><h2 id="linking-model" tabindex="-1">Linking Model <a class="header-anchor" href="#linking-model" aria-label="Permalink to &quot;Linking Model&quot;">​</a></h2><p>At link stage, <code>vex-cli</code> merges:</p><ol><li>runtime args (<code>vex_runtime</code>)</li><li>native args from package manifests (<code>vex-pm</code>)</li></ol><p>For optimized builds, ThinLTO is enabled where appropriate to reduce FFI overhead while preserving dynamic linking flexibility.</p><hr><h2 id="execution-model" tabindex="-1">Execution Model <a class="header-anchor" href="#execution-model" aria-label="Permalink to &quot;Execution Model&quot;">​</a></h2><p><code>vex run</code> compiles to a temporary executable and runs it as a subprocess. Native dependencies are resolved via the system linker and dynamic loader at runtime.</p><p><code>vex compile</code> produces a standalone binary linked against the Vex runtime static library.</p><hr><h2 id="diagnostics-and-ux" tabindex="-1">Diagnostics and UX <a class="header-anchor" href="#diagnostics-and-ux" aria-label="Permalink to &quot;Diagnostics and UX&quot;">​</a></h2><p><code>vex-cli</code> supports:</p><ul><li>JSON/non-JSON output modes</li><li>optimization remarks</li><li>sanitizer flags</li><li>coverage emission</li><li>lock-file aware dependency workflows</li></ul><hr><h2 id="key-extension-points" tabindex="-1">Key Extension Points <a class="header-anchor" href="#key-extension-points" aria-label="Permalink to &quot;Key Extension Points&quot;">​</a></h2><ul><li>Add new command: <code>tools/vex-cli/src/commands/</code></li><li>Extend CLI flags: command handler signatures + argument parser wiring</li><li>Add new link behavior: compile/run link stage argument builders</li><li>Add test behavior: <code>tools/vex-cli/src/commands/test.rs</code></li></ul><hr><h2 id="operational-notes" tabindex="-1">Operational Notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to &quot;Operational Notes&quot;">​</a></h2><ul><li>Native linking behavior is package-manifest driven (<code>vex.json/native</code>)</li><li><code>tools/vex-cli/build.rs</code> is intentionally no-op for package native logic (to avoid package-specific hardcoding)</li></ul><hr><h2 id="related-references" tabindex="-1">Related References <a class="header-anchor" href="#related-references" aria-label="Permalink to &quot;Related References&quot;">​</a></h2><ul><li><a href="/docs/guide/tooling/lint">Linting and Verified Fixes</a></li><li><a href="./vex-pm-reference">vex-pm Reference</a></li><li><a href="./vex-pm-native-ffi">vex-pm Native FFI Pipeline</a></li></ul>',57)])])}const u=i(r,[["render",l]]);export{m as __pageData,u as default};
